const html = "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n  <meta name=\"description\" content=\"公司群英志：把A股公司拟人化，用答题找到与你契合的公司英雄。\">\n  <title>公司群英志｜试玩版</title>\n  <style>\n    :root{--ink:#171a29;--muted:#777d91;--paper:#f7f7fb;--purple:#6252e7;--purple2:#8b7dff;--line:#e9e9f1;--card:#fff;--green:#168f71;--red:#ce5d61}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",\"PingFang SC\",sans-serif}button{font:inherit;border:0;cursor:pointer}button:focus-visible{outline:3px solid #b6aefe;outline-offset:3px}.shell{max-width:680px;min-height:100vh;margin:auto;background:var(--paper)}.screen{display:none;min-height:100vh}.screen.active{display:block}.top{padding:18px 22px 0;display:flex;justify-content:space-between;align-items:center}.brand{font-weight:900;letter-spacing:.02em}.nav{color:var(--muted);font-size:13px}.hero{padding:72px 28px 55px;color:#fff;background:radial-gradient(circle at 90% 0,#776cff 0,#252142 39%,#121622 100%);border-radius:0 0 34px 34px}.eyebrow{font-size:11px;letter-spacing:.16em;font-weight:800;color:#8074ef}.eyebrow.inverse{color:#bab2ff}.title{font-size:42px;line-height:1.12;letter-spacing:-.06em;font-weight:950}.hero .title{margin:18px 0}.copy{max-width:520px;color:#bfc0d0;font-size:15px;line-height:1.7}.content{padding:24px 22px 44px}.primary,.secondary,.ghost{width:100%;padding:15px 18px;border-radius:16px;font-weight:800}.primary{color:#fff;background:linear-gradient(135deg,var(--purple2),var(--purple));box-shadow:0 12px 24px #6558df35}.secondary{color:#5544d5;background:#eeecff}.ghost{color:var(--muted);background:#ececf3}.hero .primary{margin-top:28px}.resume,.card{border:1px solid var(--line);background:var(--card);border-radius:22px;box-shadow:0 10px 28px #25254508}.resume{display:flex;align-items:center;gap:12px;padding:16px;margin-bottom:30px}.resume .icon{font-size:30px}.resume .small{margin-left:auto;color:var(--purple);font-size:12px;font-weight:800}.section-head{display:flex;justify-content:space-between;align-items:end;margin:25px 0 14px}.section-title{margin-top:6px;font-weight:900;font-size:25px;letter-spacing:-.04em}.more{color:var(--purple);font-size:13px;font-weight:800}.mini-list{display:grid;gap:10px}.mini{display:flex;align-items:center;gap:12px;padding:14px}.mini-icon,.hero-icon{display:grid;place-items:center;width:45px;height:45px;border-radius:15px;color:#fff;font-size:23px}.mini-name{font-weight:850}.mini-role{display:block;color:var(--muted);font-size:12px;margin-top:3px}.disclaimer{padding:13px 15px;border-radius:14px;background:#efeff5;color:#858999;font-size:11px;line-height:1.55;margin-top:22px}.quiz{padding:22px;min-height:100vh;display:flex;flex-direction:column}.progress{height:8px;border-radius:10px;background:#e8e8f0;margin-top:12px;overflow:hidden}.progress i{display:block;height:100%;background:linear-gradient(90deg,var(--purple2),var(--purple));transition:width .25s}.quiz-main{padding-top:90px;flex:1}.question{font-weight:950;font-size:34px;line-height:1.3;letter-spacing:-.05em;margin:16px 0 38px}.answers{display:grid;gap:13px}.answer{display:flex;gap:13px;align-items:center;text-align:left;padding:18px;border:2px solid var(--line);border-radius:20px;background:#fff;color:var(--ink);font-weight:750;line-height:1.5}.answer:hover{border-color:#aaa0ff;background:#f8f7ff}.answer-key{display:grid;place-items:center;flex:none;width:36px;height:36px;border-radius:12px;background:#f0eff5;color:#777;font-weight:900}.quiz-foot{display:flex;align-items:center;gap:15px;padding:25px 0 8px}.quiz-foot .ghost{width:130px}.hint{font-size:12px;color:var(--muted)}.result-head{padding:48px 28px 34px;color:#fff;background:linear-gradient(145deg,#6658e4,#171a2a);border-radius:0 0 34px 34px}.result-icon{font-size:53px;margin-top:28px}.result-role{color:#c6c2ff;font-size:13px;margin-top:8px}.result-name{font-size:36px;font-weight:950;margin-top:5px}.motto{color:#d8d7e8;margin-top:10px}.score-row{display:flex;gap:30px;align-items:center;margin-top:32px}.score{font-size:46px;font-weight:950}.score-label{display:block;color:#b7b4c9;font-size:11px}.divider{height:48px;width:1px;background:#ffffff2a}.match-card{padding:22px;margin-top:20px}.match-item{display:flex;gap:10px;align-items:center;padding:12px 0;border-bottom:1px solid var(--line)}.match-item:last-child{border-bottom:0}.match-item span:last-child{margin-left:auto;font-weight:900;color:var(--purple)}.archive-filter{display:flex;gap:8px;overflow:auto;padding:16px 22px}.pill{white-space:nowrap;padding:9px 13px;border-radius:99px;background:#ececf3;color:var(--muted);font-size:12px}.pill.active{color:#fff;background:var(--purple)}.archive-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:0 22px 40px}.archive{padding:18px;min-height:190px}.archive .hero-icon{margin-bottom:14px}.archive-role{font-size:11px;font-weight:800}.archive-name{display:block;font-size:21px;font-weight:950;margin:4px 0}.archive-motto{color:var(--muted);font-size:12px;line-height:1.45}.detail-head{padding:44px 26px;color:#fff;border-radius:0 0 34px 34px}.detail-body{padding:22px}.detail-card{padding:21px;margin-bottom:14px}.axis{display:grid;grid-template-columns:88px 1fr 34px;align-items:center;gap:8px;margin-top:15px;font-size:12px}.axis-bar{height:7px;border-radius:8px;background:#eeeef4;overflow:hidden}.axis-bar i{display:block;height:100%;border-radius:8px;background:var(--purple)}.tradeoff{margin-top:18px;padding:13px;border-radius:14px;background:#f4f3fa;color:#6c7180;font-size:12px;line-height:1.55}.arena-head{padding:42px 25px 58px;color:#fff;background:radial-gradient(circle at 90% 0,#7770ff,#242044 44%,#141722 100%);border-radius:0 0 34px 34px}.arena-body{padding:20px 22px}.selected{display:flex;flex-wrap:wrap;gap:8px;min-height:51px;padding:12px;border-radius:16px;background:#ecebf4;margin:13px 0}.token{padding:7px 10px;border-radius:9px;background:#fff;color:var(--purple);font-size:12px;font-weight:800}.roster{display:grid;grid-template-columns:1fr 1fr;gap:10px}.pick{display:flex;align-items:center;gap:8px;text-align:left;padding:11px;border:2px solid transparent;border-radius:16px;background:#fff}.pick.on{border-color:var(--purple);background:#f0efff}.pick .hero-icon{width:36px;height:36px;border-radius:12px;font-size:18px}.pick small{display:block;color:var(--muted);font-size:10px;margin-top:2px}.battle{padding:22px;color:#fff;background:linear-gradient(140deg,#282548,#171a2b);border-radius:24px}.versus{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:12px;margin-top:28px}.team:last-child{text-align:right}.team small{color:#b8b5cf}.big{display:block;font-size:41px;font-weight:950;color:#fa9090}.big.win{color:#7be1ba}.vs{color:#8c88af;font-weight:950}.days{display:grid;grid-template-columns:repeat(5,1fr);gap:7px;margin-top:15px}.day{padding:10px 2px;border-radius:13px;background:#e9e9f0;color:var(--muted);font-size:10px}.day.active{background:var(--purple);color:#fff}.day b{display:block;margin-top:4px}.daily{padding:20px;margin-top:14px}.daily strong{font-size:27px}.daily-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:18px}.daily-grid div{padding:12px;background:#f5f5f8;border-radius:13px}.daily-grid span{display:block;color:var(--muted);font-size:11px;margin-bottom:5px}.bottom-nav{position:sticky;bottom:0;display:grid;grid-template-columns:repeat(3,1fr);gap:4px;padding:9px 15px calc(9px + env(safe-area-inset-bottom));background:#fffffff0;border-top:1px solid var(--line);backdrop-filter:blur(10px)}.bottom-nav button{padding:9px 2px;background:transparent;color:var(--muted);font-size:12px}.bottom-nav button.active{color:var(--purple);font-weight:900}@media(max-width:450px){.title{font-size:37px}.question{font-size:30px}.archive-grid{grid-template-columns:1fr 1fr}.roster{grid-template-columns:1fr}}\n  </style>\n</head>\n<body><main class=\"shell\" id=\"app\"></main>\n<script>\nconst heroes=[\n {id:'catl',name:'宁德时代',role:'探索者',industry:'新能源',icon:'⚡',color:'#735cff',motto:'把不可能做成日常',mission:'用技术和制造，把能源的边界再推远一点。',strengths:['持续创新','长期主义','工程落地'],tradeoff:'研发投入高、节奏快，需要持续下注未来。',axes:[92,82,78,61,68,72,86,73,51,88]},\n {id:'crrc',name:'中国中车',role:'基建者',industry:'高端制造',icon:'🚄',color:'#ef756d',motto:'让连接发生',mission:'把复杂的系统，变成可靠的出行与连接。',strengths:['系统工程','安全可靠','产业协同'],tradeoff:'决策链条长，兑现往往需要时间。',axes:[55,94,86,92,76,96,73,98,82,97]},\n {id:'midea',name:'美的集团',role:'生活家',industry:'家电消费',icon:'🏠',color:'#ef9b4e',motto:'把日子过得更聪明',mission:'从一个家庭的真实需求出发，做更好用的产品。',strengths:['用户洞察','效率优先','全球运营'],tradeoff:'品类多、组织复杂，取舍需要极强执行力。',axes:[73,88,72,81,96,69,78,66,91,79]},\n {id:'mindray',name:'迈瑞医疗',role:'守护者',industry:'医疗器械',icon:'✚',color:'#33b996',motto:'让每一次守护更有底气',mission:'用可靠的医疗设备，让专业照顾更多生命。',strengths:['专业深耕','质量第一','稳定复利'],tradeoff:'行业门槛高，增长更依赖长期积累。',axes:[66,95,98,72,84,79,64,71,87,94]},\n {id:'sf',name:'顺丰控股',role:'连接者',industry:'物流服务',icon:'✈',color:'#f07d58',motto:'把远方变成准时抵达',mission:'让人与货物在更短时间内抵达彼此。',strengths:['服务意识','网络协同','时效管理'],tradeoff:'重资产和高服务标准，规模越大越考验管理。',axes:[78,86,69,96,88,74,82,70,93,81]},\n {id:'byd',name:'比亚迪',role:'破局者',industry:'智能汽车',icon:'🚙',color:'#4f7ae8',motto:'在变化里重新发明',mission:'用垂直整合和技术，把复杂的产品做得更普及。',strengths:['快速迭代','垂直整合','成本创新'],tradeoff:'竞争强、迭代快，需要接受阶段性波动。',axes:[95,89,81,75,83,88,79,80,62,77]},\n {id:'mobile',name:'中国移动',role:'连接者',industry:'通信服务',icon:'📡',color:'#5a9be8',motto:'让每个人都在线',mission:'用基础设施连接生活、产业与未来。',strengths:['基础设施','普惠连接','长期建设'],tradeoff:'体量大、创新慢，优势来自时间和网络效应。',axes:[59,92,80,94,90,97,91,65,96,98]},\n {id:'longi',name:'隆基绿能',role:'探索者',industry:'光伏能源',icon:'☀',color:'#4ca9a4',motto:'把阳光变成确定性',mission:'让清洁能源更高效、更普惠地走进生活。',strengths:['技术路线','效率提升','全球视野'],tradeoff:'周期波动明显，技术选择需要耐心。',axes:[90,90,86,67,73,77,88,75,58,90]}\n];\nconst qs=[\n ['当资源有限时，你会优先？','把钱投向下一代技术','把现有流程做到极致'],['团队遇到新问题，你更像？','先试一个小方案','先把标准和边界定清楚'],['面对长期目标，你会？','持续下注未来','一步一步做出复利'],['客户提出模糊需求，你会？','从场景里找机会','先问清楚再交付'],['业务做大后，你最重视？','组织持续学习','系统稳定可靠'],['同行加速竞争，你会？','重新定义赛道','把服务和品质做到更稳'],['你更享受哪种成就？','创造一个新答案','让复杂系统稳定运行'],['朋友评价你最常说？','总能想到新点子','特别靠谱、说到做到']\n].map((x,i)=>({id:i,caption:`SCENARIO ${String(i+1).padStart(2,'0')}`,text:x[0],options:[{text:x[1],delta:[7,2,5,0,2,1,5,3,0,4]},{text:x[2],delta:[0,7,3,5,5,6,1,7,6,7]}]}));\nlet state={screen:'home',q:0,answers:[],result:null,selected:[],day:2};\nconst app=document.getElementById('app');\nfunction esc(s){return String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]))}\nfunction nav(){return `<nav class=\"bottom-nav\"><button class=\"${state.screen==='home'?'active':''}\" onclick=\"go('home')\">探索</button><button class=\"${state.screen==='archive'?'active':''}\" onclick=\"go('archive')\">群英录</button><button class=\"${state.screen==='arena'?'active':''}\" onclick=\"go('arena')\">试炼场</button></nav>`}\nfunction score(){const v=Array(10).fill(55);state.answers.forEach(a=>a.delta.forEach((n,i)=>v[i]+=n));const ranked=heroes.map(h=>({...h,matchScore:Math.max(58,Math.min(96,Math.round(100-v.reduce((s,n,i)=>s+Math.abs(n/(state.answers.length/6+1)-h.axes[i]),0)/10)))})).sort((a,b)=>b.matchScore-a.matchScore);return {primary:ranked[0],companion:ranked[1],contrast:ranked[ranked.length-1],confidence:Math.min(95,55+state.answers.length*3)}}\nfunction heroMini(h){return `<div class=\"mini card\" onclick=\"detail('${h.id}')\"><span class=\"mini-icon\" style=\"background:${h.color}\">${h.icon}</span><div><b class=\"mini-name\">${h.name}</b><span class=\"mini-role\">${h.role} · ${h.motto}</span></div></div>`}\nfunction render(){if(state.screen==='home')home();if(state.screen==='quiz')quiz();if(state.screen==='result')result();if(state.screen==='archive')archive();if(state.screen==='detail')detailPage();if(state.screen==='arena')arena();}\nfunction home(){app.innerHTML=`<section class=\"screen active\"><div class=\"top\"><span class=\"brand\">公司群英志</span><span class=\"nav\">试玩版 · 非投资建议</span></div><div class=\"hero\"><div class=\"eyebrow inverse\">A-SHARE COMPANY PERSONALITY</div><div class=\"title\">如果你是一家公司，<br>你会怎样赢？</div><div class=\"copy\">用经营人格找到和你更契合的公司英雄。这里不预测涨跌，只聊长期的做事方式。</div><button class=\"primary\" onclick=\"startQuiz()\">开始人格探索</button></div><div class=\"content\">${state.result?`<div class=\"resume card\" onclick=\"go('result')\"><span class=\"icon\">${state.result.primary.icon}</span><div><b>${state.result.primary.name}</b><small class=\"mini-role\">你的本命英雄</small></div><span class=\"small\">查看结果 →</span></div>`:''}<div class=\"section-head\"><div><div class=\"eyebrow\">HEROES TO MEET</div><div class=\"section-title\">先认识几位英雄</div></div><span class=\"more\" onclick=\"go('archive')\">全部 →</span></div><div class=\"mini-list\">${heroes.slice(0,5).map(heroMini).join('')}</div><div class=\"disclaimer\">本产品用于公司经营特征的内容探索，不构成证券投资、交易或收益建议。</div></div>${nav()}</section>`}\nfunction startQuiz(){state={...state,screen:'quiz',q:0,answers:[]};render()}\nfunction quiz(){const q=qs[state.q];app.innerHTML=`<section class=\"screen active quiz\"><div class=\"quiz-top\"><div class=\"quiz-meta\"><span>经营人格探索</span><span>${state.q+1} / ${qs.length}</span></div><div class=\"progress\"><i style=\"width:${(state.q+1)/qs.length*100}%\"></i></div></div><div class=\"quiz-main\"><div class=\"eyebrow\">${q.caption}</div><div class=\"question\">${q.text}</div><div class=\"answers\">${q.options.map((o,i)=>`<button class=\"answer\" onclick=\"answer(${i})\"><span class=\"answer-key\">${i?'B':'A'}</span>${o.text}</button>`).join('')}</div></div><div class=\"quiz-foot\"><button class=\"ghost\" onclick=\"previous()\">${state.q?'上一题':'退出'}</button><span class=\"hint\">点击选项后自动进入下一题</span></div><div class=\"disclaimer\">你的答案只用于生成人格画像；不收集持仓、资产或交易信息。</div></section>`}\nfunction answer(i){state.answers.push({delta:qs[state.q].options[i].delta});if(state.q===qs.length-1){state.result=score();state.screen='result'}else state.q++;render()}\nfunction previous(){if(!state.q)return go('home');state.q--;state.answers.pop();render()}\nfunction result(){const r=state.result;app.innerHTML=`<section class=\"screen active\"><div class=\"result-head\"><div class=\"eyebrow inverse\">YOUR COMPANY HERO</div><div class=\"result-icon\">${r.primary.icon}</div><div class=\"result-role\">${r.primary.role}</div><div class=\"result-name\">${r.primary.name}</div><div class=\"motto\">${r.primary.motto}</div><div class=\"score-row\"><div><b class=\"score\">${r.primary.matchScore}</b><span>/100</span><small class=\"score-label\">人格契合指数</small></div><div class=\"divider\"></div><div><b class=\"score\">${r.confidence}</b><span>%</span><small class=\"score-label\">结果置信度</small></div></div></div><div class=\"content\"><div class=\"disclaimer\">契合度只描述你与经营特征的相似程度，不表示投资收益、上涨概率或买卖建议。</div><div class=\"match-card card\"><div class=\"eyebrow\">WHY YOU MATCH</div><div class=\"section-title\">你们的三个同频点</div>${r.primary.strengths.map(s=>`<div class=\"match-item\">● ${s}</div>`).join('')}<div class=\"tradeoff\"><b>真实取舍：</b>${r.primary.tradeoff}</div></div><div class=\"section-head\"><div><div class=\"eyebrow\">YOUR OTHER SIDES</div><div class=\"section-title\">还有两种可能的你</div></div></div>${[r.companion,r.contrast].map((h,i)=>`<div class=\"mini card\" onclick=\"detail('${h.id}')\"><span class=\"mini-icon\" style=\"background:${h.color}\">${h.icon}</span><div><b>${i?'反差英雄':'同频搭档'} · ${h.name}</b><span class=\"mini-role\">${h.role}</span></div><span class=\"small\">${h.matchScore}</span></div>`).join('')}<button class=\"primary\" style=\"margin-top:18px\" onclick=\"go('arena')\">组 5 位英雄，发起好友试炼</button><button class=\"ghost\" style=\"margin-top:10px\" onclick=\"startQuiz()\">重新探索</button></div>${nav()}</section>`}\nfunction archive(){app.innerHTML=`<section class=\"screen active\"><div class=\"hero\" style=\"padding:42px 25px\"><div class=\"eyebrow inverse\">COMPANY HERO ARCHIVE</div><div class=\"title\">群英录</div><div class=\"copy\">每位英雄是一种经营方式，而非一条买卖建议。</div></div><div class=\"archive-filter\">${['全部',...new Set(heroes.map(h=>h.role))].map((x,i)=>`<button class=\"pill ${i===0?'active':''}\">${x}</button>`).join('')}</div><div class=\"archive-grid\">${heroes.map(h=>`<div class=\"archive card\" onclick=\"detail('${h.id}')\"><span class=\"hero-icon\" style=\"background:${h.color}\">${h.icon}</span><div class=\"archive-role\" style=\"color:${h.color}\">${h.role}</div><div class=\"archive-name\">${h.name}</div><div class=\"archive-motto\">${h.motto}</div></div>`).join('')}</div>${nav()}</section>`}\nfunction detail(id){state.detail=heroes.find(h=>h.id===id)||heroes[0];state.screen='detail';render()}\nfunction detailPage(){const h=state.detail;app.innerHTML=`<section class=\"screen active\"><div class=\"detail-head\" style=\"background:${h.color}\"><div class=\"result-icon\">${h.icon}</div><div class=\"result-role\">${h.role} · ${h.industry}</div><div class=\"result-name\">${h.name}</div><div class=\"motto\">${h.motto}</div></div><div class=\"detail-body\"><div class=\"disclaimer\">英雄档案展示公司公开经营特征摘要，不构成投资建议。</div><div class=\"detail-card card\"><div class=\"section-title\">这位英雄的任务</div><p>${h.mission}</p>${h.facts?`<div class=\"tradeoff\">${h.facts.join(' · ')}</div>`:''}</div><div class=\"detail-card card\"><div class=\"section-title\">经营人格坐标</div>${['探索力','精益力','专注度','协同度','生活贴近度','产业底座度','全球连接度','工程建造度','需求稳定度','长周期建设度'].map((x,i)=>`<div class=\"axis\"><span>${x}</span><span class=\"axis-bar\"><i style=\"width:${h.axes[i]}%;background:${h.color}\"></i></span><span>${h.axes[i]}</span></div>`).join('')}</div><div class=\"detail-card card\"><div class=\"section-title\">擅长与取舍</div><p>${h.strengths.join(' · ')}</p><div class=\"tradeoff\"><b>真实取舍：</b>${h.tradeoff}</div></div><button class=\"primary\" onclick=\"go('arena')\">带他去好友试炼场</button><button class=\"ghost\" style=\"margin-top:10px\" onclick=\"go('archive')\">返回群英录</button></div></section>`}\nfunction arena(){const selected=state.selected.map(id=>heroes.find(h=>h.id===id));if(state.battle){const p=state.battle.player[state.day],r=state.battle.rival[state.day];app.innerHTML=`<section class=\"screen active\"><div class=\"arena-head\"><div class=\"eyebrow inverse\">FRIENDS ONLY · 5 DAY DUEL</div><div class=\"title\" style=\"font-size:34px;margin-top:15px\">收盘试炼战报</div><div class=\"copy\">演示数据 · 每日收盘后结算 · 不构成投资建议</div></div><div class=\"arena-body\"><div class=\"battle\"><div class=\"nav\">第 ${state.day+1} / 5 个交易日</div><div class=\"versus\"><div class=\"team\"><small>我的英雄队</small><b class=\"big ${p.score>=r.score?'win':''}\">${p.sign}${p.score}</b></div><div class=\"vs\">VS</div><div class=\"team\"><small>好友的守城队</small><b class=\"big ${r.score>p.score?'win':''}\">${r.sign}${r.score}</b></div></div><div class=\"days\">${state.battle.player.map((d,i)=>`<button class=\"day ${i===state.day?'active':''}\" onclick=\"day(${i})\">第${i+1}天<b>${d.sign}${d.score}</b></button>`).join('')}</div></div><div class=\"daily card\"><div class=\"eyebrow\">TODAY'S REPORT</div><div class=\"section-title\">${p.score>=r.score?'今天，你的队伍暂时领先。':'今天，朋友的队伍暂时领先。'}</div><div class=\"daily-grid\"><div><span>我的原始平均表现</span><strong>${p.sign}${p.raw}%</strong></div><div><span>朋友队表现</span><strong>${r.sign}${r.raw}%</strong></div></div><div class=\"disclaimer\">市场战绩仅代表本轮价格表现，不改变英雄人格，也不构成交易建议。</div></div><button class=\"secondary\" onclick=\"newBattle()\">重新组队</button></div>${nav()}</section>`;return}app.innerHTML=`<section class=\"screen active\"><div class=\"arena-head\"><div class=\"eyebrow inverse\">FRIENDS ONLY · 5 DAY DUEL</div><div class=\"title\" style=\"font-size:34px;margin-top:15px\">5 位英雄，<br>一场收盘试炼。</div><div class=\"copy\">手动组队、好友盲选、锁定 5 个交易日，每天收盘后生成战报。</div></div><div class=\"arena-body\"><div class=\"disclaimer\">演示版使用预置模拟收盘数据。正式版本须接入合法授权行情。</div><div class=\"section-head\"><div><div class=\"section-title\">组建你的战队</div><div class=\"nav\">固定 5 位 · 点击卡片选择</div></div><b style=\"font-size:25px;color:var(--purple)\">${selected.length}/5</b></div><div class=\"selected\">${selected.length?selected.map(h=>`<span class=\"token\">${h.name}</span>`).join(''):'<span class=\"nav\">从下面挑选 5 位英雄</span>'}</div><div class=\"roster\">${heroes.map(h=>`<button class=\"pick ${state.selected.includes(h.id)?'on':''}\" onclick=\"pick('${h.id}')\"><span class=\"hero-icon\" style=\"background:${h.color}\">${h.icon}</span><span><b>${h.name}</b><small>${h.role}</small></span></button>`).join('')}</div><button class=\"primary\" style=\"margin-top:20px\" onclick=\"lockBattle()\">锁定阵容，生成演示战报</button></div>${nav()}</section>`}\nfunction pick(id){if(state.selected.includes(id))state.selected=state.selected.filter(x=>x!==id);else if(state.selected.length<5)state.selected.push(id);render()}\nfunction lockBattle(){if(state.selected.length!==5)return alert('请先选满 5 位英雄');const returns={catl:[1.7,-.8,2.3,.6,1.2],crrc:[.4,.7,-.3,1.1,.3],midea:[.6,.2,.5,-.4,.8],mindray:[-.2,.9,.4,.2,.5],sf:[1,-.1,-.5,.9,.2],byd:[2.1,-1.4,1.3,.3,1.8],mobile:[.3,.5,.1,-.1,.4],longi:[-.9,1.2,.8,-.6,1]};const rival=['crrc','midea','mindray','mobile','longi'];const make=ids=>[0,1,2,3,4].map(i=>{const vals=ids.map(id=>(returns[id]||[0,0,0,0,0])[i]);const raw=+(vals.reduce((a,b)=>a+b,0)/vals.length).toFixed(2);return {raw,score:raw,sign:raw>0?'+':''}});state.battle={player:make(state.selected),rival:make(rival)};state.day=2;render()}\nfunction day(i){state.day=i;render()}function newBattle(){state.battle=null;state.selected=[];render()}function go(screen){state.screen=screen;render()}go('home');\n</script></body></html>\n"; export default { async fetch() { return new Response(html, { headers: { 'content-type': 'text/html; charset=utf-8' } }); } };